selector_to_html = {"a[href=\"capabilities.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Capability reference<a class=\"headerlink\" href=\"#capability-reference\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum publishes the maturity of every capability instead of implying it\nfrom an example. This page is a summary; the repository\u2019s machine-validated\ncapability matrix is authoritative.</p>", "a[href=\"#stability-boundaries\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Stability boundaries<a class=\"headerlink\" href=\"#stability-boundaries\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#further-reading\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Further reading<a class=\"headerlink\" href=\"#further-reading\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#errors\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Errors<a class=\"headerlink\" href=\"#errors\" title=\"Link to this heading\">#</a></h2><p>All categories inherit <code class=\"docutils literal notranslate\"><span class=\"pre\">FlagQuantumError</span></code> and a compatible Python built-in\nexception. Wrong Python types and unknown keyword arguments raise <code class=\"docutils literal notranslate\"><span class=\"pre\">TypeError</span></code>.</p>", "a[href=\"#operators\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Operators<a class=\"headerlink\" href=\"#operators\" title=\"Link to this heading\">#</a></h2><p>Circuit operations and backend lowering availability derive from one typed\noperator registry. A registered lowering means the operator can be lowered for\nthat backend \u2014 not that it is release evidence. The generated operator table in\nthe repository is authoritative for the registered set, which covers Pauli,\nClifford, rotation, controlled, symmetric two-qubit and phase gates, plus the\nnoise channels used by the stable noise model.</p>", "a[href=\"#api-map\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">API map<a class=\"headerlink\" href=\"#api-map\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../FlagQuantum_overview/architecture.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Architecture<a class=\"headerlink\" href=\"#architecture\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum gives quantum AI programs one public model across local\ndevelopment, accelerated kernels, distributed simulation and deployment. It is\norganized so that a backend change never changes the meaning of a program.</p>", "a[href=\"#reference\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Reference<a class=\"headerlink\" href=\"#reference\" title=\"Link to this heading\">#</a></h1><p>Stable interfaces, configuration and support boundaries.</p>", "a[href=\"#runtime-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Runtime configuration<a class=\"headerlink\" href=\"#runtime-configuration\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">RuntimeConfig</span></code> is FlagQuantum\u2019s immutable execution policy: backend, device,\nreal and complex precision, JAX precision, matrix multiplication policy and\ndrawing style. A <code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit</span></code> captures a configuration when constructed and embeds\na versioned manifest in IR and execution plans, so distributed workers rebuild\nthe same policy.</p>", "a[href=\"#stable-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Stable API<a class=\"headerlink\" href=\"#stable-api\" title=\"Link to this heading\">#</a></h2><p>FlagQuantum exposes one curated Python interface, <code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">flagquantum</span> <span class=\"pre\">as</span> <span class=\"pre\">fq</span></code>.\nThe stable names are bounded by a checked manifest, verified by executable\ncontract tests.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
